#!/usr/bin/env bash
# Does the fork reproduce the numbers the patch-overlay build produced?
#
#   run_fork_verify.sh [reps]        default: 50
#
# WHAT CHANGED BETWEEN THE TWO BUILDS, and why this is not a formality:
#
#   * The overlay build was five files copied over site-packages, driven by env vars
#     (PA_SESSION / PA_APPEND_ONLY / PA_EVS_*). The fork drives everything from
#     session.config instead, so the code that reads the settings is different.
#   * The overlay pre-shrank frames OFFLINE: the stimulus directory frames640/ was
#     generated by a script, and the server only ever saw 640x352. The fork does the
#     downscaling itself, on arrival. So this run feeds the ORIGINAL 1280x720 frames and
#     makes the server shrink them -- which tests the new code path rather than assuming
#     it matches.
#   * The EVS gap bracket is now applied through a public filter method
#     (force_next_retain) instead of assigning to the filter's private attribute.
#
# So four of the seven commits are on the path this exercises.
#
# ONE INTENDED DIFFERENCE, measured rather than assumed. The offline script squashed
# 1280x720 (16:9) into exactly 640x352 (20:11) = 220 tokens/frame. The fork preserves
# aspect ratio, so fitting 1280x720 inside 640x352 gives 625x352 = 209 tokens/frame, 5%
# fewer. Per-turn TTFA is therefore expected slightly LOWER at a given turn index, which
# is why the metric of record is the SLOPE in ms per 1,000 ACCUMULATED tokens: dividing by
# token count removes the difference instead of hiding it.
#
# max_frames is 256 here, not the overlay's 284: upstream's field caps it at 256 and the
# overlay had raised that bound. It makes no difference now -- session mode drains the
# buffer every turn, so it holds a handful of frames and never approaches either cap.
#
# The fork is loaded via PYTHONPATH rather than `pip install -e`, deliberately: it leaves
# the environment exactly as it was, and the check below asserts which copy actually got
# imported rather than trusting it.
#
# REFERENCE, from the overlay build (2 sessions x 50 turns, n=100):
#   talker+code2wav slope  2.13 ms per 1,000 accumulated prompt tokens
#   TTFA p50 360 ms, p99 494 ms, max 514 ms, 0 turns over 600 ms
#   talker placeholder held at median 598 tokens while the prompt reached 33,772
#
# WHAT RUN A (2026-07-31 00:29) FOUND, and what changed for this run. Run A reproduced the
# slope -- 3.17 ms/1k against 2.13, both an order of magnitude under the 36.5 of the best
# per-turn build -- but the session DIED at turn 28: the client got first_text and then no
# audio, the turn boundary never arrived, and the client's next query was labelled turn 28 a
# second time. The overlay ran two 50-turn sessions with no such failure, reaching a LARGER
# accumulated prompt (34,070 and 36,289) than the fork had at the point it broke (28,140), so
# context length alone does not explain it.
#
# Run A's turns were consistently fatter than the overlay's: 3-4 retained frames per turn
# against 2-3, talker placeholder 1105 against 598. Delta size is coupled to turn DURATION
# here -- frames arrive while the turn is being answered, so a slower turn retains more
# frames, which makes the next turn slower still. Two fixes since run A act on exactly that
# loop, which is why this is re-run rather than reported from run A:
#   * 6ec99006 moves the frame downscale off the event loop, which run A was charging to the
#     time-to-first-audio of whatever turn was speaking (the overlay never ran that code --
#     its frames were shrunk offline -- so run A was charged for work its reference never did)
#   * b7392f3c makes the resumable-teardown park actually fire (9fdee244 swept the wrong queue)
set -uo pipefail
source /home/zx/voice-agent/env.sh

REPS="${1:-50}"
FORK=/home/zx/voice-agent/vllm-omni
RES=/data/zx/results
H=/home/zx/voice-agent/vllm-omni/benchmarks/live_agent/harness
CFG=$H/deploy_pc_stage0.yaml
# The ORIGINAL frames, not the pre-shrunk ones: the server downscales now.
F720=/data/zx/stimuli/frames/handheld_walk_talk
LOG=$RES/server_fork.log
OUT=$RES/vt_u1_FORK_high
SMOKE=$RES/fork_smoke

mkdir -p "$SMOKE"; rm -rf "$OUT"; mkdir -p "$OUT"

# Matched to the S640 arm so the numbers are comparable.
CLIENT_ARGS=(--num-frames 16 --max-frames 256 --evs --evs-threshold 0.95 --trace-deltas
             --max-frame-width 640 --max-frame-height 352
             --frame-filter-min-gap 8 --frame-filter-max-gap 16
             --session-scoped-request)

kill_all() {
  local pids
  pids=$(ps -eo pid=,args= | awk -v me=$$ '/cli.main serve|vllm serve/ && !/awk/ && $1!=me {print $1}')
  [ -n "$pids" ] && for p in $pids; do kill -TERM "$p" 2>/dev/null; done
  sleep 6
  [ -n "$pids" ] && for p in $pids; do kill -KILL "$p" 2>/dev/null; done
  for i in $(seq 1 40); do
    used=$(nvidia-smi --query-gpu=memory.used --format=csv,noheader,nounits)
    left=$(ps -eo pid=,args= | awk -v me=$$ '/cli.main serve/ && !/awk/ && $1!=me {print $1}' | wc -l)
    [ "$used" -lt 1000 ] && [ "$left" -eq 0 ] && break
    sleep 3
  done
}

boot() {          # label
  printf "\n===== FORK %s %s =====\n" "$1" "$(date -Is)" >> "$LOG"
  echo ""
  echo "################ server up: $1 ################"
  # SESSION_OUTPUTS logs one line per engine output (type / stage / finish_reason / token
  # count / audio count). It is on because run A died at turn 28 in a way that left NO
  # evidence: the client got first_text and then no audio, the boundary never arrived, and
  # the server logged no error, no traceback and no length violation. The boundary is
  # detected from a finish_reason on an AUDIO output, so the question "did the engine stop
  # emitting audio outputs, or did it emit them without a finish_reason" is the whole
  # diagnosis, and nothing in the default log distinguishes those. TRANSFER is cheap
  # (per-turn, not per-output) and gives the payload size the talker was charged for.
  HF_HOME=/data/zx/hf CUDA_VISIBLE_DEVICES=0 PYTHONPATH="$FORK" \
  VLLM_OMNI_LOG_SESSION_OUTPUTS=1 VLLM_OMNI_LOG_TRANSFER=1 \
  nohup $PY_OMNI -m vllm.entrypoints.cli.main serve Qwen/Qwen3-Omni-30B-A3B-Instruct \
    --omni --port 8091 --deploy-config "$CFG" \
    --init-timeout 3000 --stage-init-timeout 1500 >> "$LOG" 2>&1 &
  for i in $(seq 1 300); do
    code=$(timeout 3 curl -s -o /dev/null -w "%{http_code}" http://127.0.0.1:8091/health 2>/dev/null)
    if [ "$code" = "200" ]; then echo "  ready after ~$((i*5))s"; return 0; fi
    if grep -qiE "not enough GPU memory|Engine core initialization failed" "$LOG"; then
      echo "  SERVER FAILED"; tail -20 "$LOG" | cut -c1-170; return 1
    fi
    sleep 5
  done
  echo "  TIMEOUT"; return 1
}

# ---- 0. prove the FORK is what gets imported, not site-packages --------------------
echo "==== which vllm_omni will the server load? ===="
PYTHONPATH="$FORK" $PY_OMNI -c "
import vllm_omni, os, sys
p = os.path.dirname(vllm_omni.__file__)
print('  ', p)
assert '/voice-agent/vllm-omni/' in p, 'NOT the fork -- aborting'
import vllm_omni.entrypoints.openai.video_stream_base as B
f = B.StreamingVideoSessionConfig.model_fields
for k in ('session_scoped_request','max_frame_width','frame_filter_min_gap','frame_filter_max_gap'):
    assert k in f, k
print('   fork config fields present, session_scoped_request default =',
      B.StreamingVideoSessionConfig().session_scoped_request)
" 2>&1 | grep -vE "NVFP4|RuntimeWarning|from .version|^This typically|^Using fallback" || { echo "!! fork not importable"; exit 1; }

if [ -z "$(find "$F720" -maxdepth 1 -type f -name '*.jpg' -print -quit)" ]; then
  echo "!! no frames in $F720"; exit 1
fi
echo "  stimulus: $F720 ($(find "$F720" -maxdepth 1 -name '*.jpg' | wc -l) frames, ORIGINAL resolution)"

kill_all

# ---- 1. ladder: 3 turns, then 12, gated -------------------------------------------
boot "ladder" || { kill_all; exit 1; }
for n in 3 12; do
  echo ""
  echo "---- rung: $n turns ----"
  rm -rf "$SMOKE/r$n"; mkdir -p "$SMOKE/r$n"
  timeout 1200 $PY_OMNI $H/ttfa_bench.py --users 1 --reps "$n" --outdir "$SMOKE/r$n" \
    --frames "$F720" "${CLIENT_ARGS[@]}" 2>&1 | tail -2
  sleep 3
  if ! $PY_PA0 $H/check_session.py --log "$LOG" --expect-turns "$n" --trace "$SMOKE/r$n" \
        --marker "===== FORK"; then
    echo "!! rung $n FAILED the gate"; kill_all; exit 1
  fi
  kill_all
  boot "after-r$n" || { kill_all; exit 1; }
done

# ---- 2. the arm: one 50-turn session ----------------------------------------------
echo ""
echo "================ FORK arm: $REPS turns ================"
$PY_PA0 $H/gpu_sampler.py --out $RES/gpu_vt_u1_FORK_high.jsonl --hz 50 --duration-s 5000 &
gs=$!
sleep 1
timeout 4000 $PY_OMNI $H/ttfa_bench.py --users 1 --reps "$REPS" --outdir "$OUT" --session 1 \
  --frames "$F720" "${CLIENT_ARGS[@]}" 2>&1 | tail -2
kill $gs 2>/dev/null; wait $gs 2>/dev/null

kill_all
echo ""
echo "################################################################"
echo "# fork verification done. Compare against the overlay build:"
echo "#   analysis/fork_compare.py"
echo "################################################################"
